import { type AgentJobDatabase, createAgentJob } from "./job-store"

export async function submitRun(db: AgentJobDatabase, intent: { prompt: string }) {
  const job = await createAgentJob(db, intent as never)
  return { job, replay: false }
}

export async function waitForRun(db: AgentJobDatabase, jobId: string, options: { timeoutMs: number }) {
  return { db, jobId, timeoutMs: options.timeoutMs }
}

import { runPersistedCompletionJob } from "./completion-runner"
import { runPersistedAgentJob } from "./job-runner"
import { type AgentJobDatabase, listQueuedAgentJobsForSource } from "./job-store"

export async function pumpQueuedRuns(input: { db: AgentJobDatabase; admittedIds?: readonly string[] }) {
  for (const job of listQueuedAgentJobsForSource(input.db, "api", 10)) {
    if (input.admittedIds && !input.admittedIds.includes(job.id)) continue
    if (job.kind === "completion") await runPersistedCompletionJob({ db: input.db, jobId: job.id })
    else await runPersistedAgentJob({ db: input.db, jobId: job.id })
  }
}

export async function runLocalAgentDaemon(options: { db: AgentJobDatabase }) {
  await pumpQueuedRuns({ db: options.db })
}

