import { type AgentJobDatabase, cancelAgentJob, listQueuedAgentJobsForSource, startAgentJob } from "./job-store"
import { submitRun } from "./run-submission"

type Session = { db: AgentJobDatabase; admittedIds: Set<string>; runner: (jobId: string) => Promise<void> }

// an independently dispatching session loop instead of the canonical pump
async function dispatchSessionQueue(session: Session) {
  for (const job of listQueuedAgentJobsForSource(session.db, "protocol", 10)) {
    if (!session.admittedIds.has(job.id)) continue
    await startAgentJob(session.db, { jobId: job.id, workerId: "protocol-session-loop" })
    await session.runner(job.id)
  }
}

export async function handleJobRun(session: Session, params: { prompt: string }) {
  const admission = await submitRun(session.db, params)
  session.admittedIds.add(admission.job.id)
  void dispatchSessionQueue(session)
  return { job: admission.job }
}

