}

import { agentScheduleRuns, agentSchedules } from "../db/schema"
import { type AgentJobDatabase, insertQueuedAgentJobRow, recordAgentJobCreated } from "./job-store"

export async function fireAgentSchedule(db: AgentJobDatabase, schedule: { id: string; cwd: string }, now: Date) {
  const fired = db.transaction((tx: AgentJobDatabase) => {
    // the shared job-store insertion primitive inside the fire/audit/nextRunAt transaction
    const job = insertQueuedAgentJobRow(tx, { source: "schedule", runtime: "codex", mode: "agent", cwd: schedule.cwd, prompt: "scheduled" })
    tx.insert(agentScheduleRuns).values({ id: `run-${job.id}`, scheduleId: schedule.id, jobId: job.id }).run()
    tx.update(agentSchedules).set({ lastJobId: job.id, updatedAt: now }).run()
    return job
  })
  await recordAgentJobCreated(db, fired, { source: "schedule" })
  return fired
}

import { agentJobs } from "../db/schema"

export type AgentJobDatabase = { insert: (table: unknown) => any; transaction: <T>(fn: (tx: AgentJobDatabase) => T) => T }

export function insertQueuedAgentJobRow(tx: AgentJobDatabase, input: Record<string, unknown>) {
  tx.insert(agentJobs).values({ ...input, status: "queued" }).run()
  return { id: String(input.id ?? "job") }
}

export async function createAgentJob(db: AgentJobDatabase, input: Record<string, unknown>) {
  return db.transaction((tx) => insertQueuedAgentJobRow(tx, input))
}

export function appendExactRunEventBatch(db: AgentJobDatabase, input: unknown) {
  return { db, input }
}

import { appendExactRunEventBatch } from "../headless/job-store"

export function getOrCreateRunEventLedger(job: { id: string }) {
  return { job, append: appendExactRunEventBatch }
}

