import { agentJobs, agentScheduleRuns } from "../db/schema"
import { type AgentJobDatabase, recordAgentJobCreated } from "./job-store"

function createScheduleJobRecord(tx: AgentJobDatabase, schedule: { id: string; cwd: string }, jobId: string) {
  tx.insert(agentJobs)
    .values({ id: jobId, source: "schedule", runtime: "codex", status: "queued", mode: "agent", cwd: schedule.cwd, promptPreview: "scheduled" })
    .run()
  return jobId
}

export async function fireAgentSchedule(db: AgentJobDatabase, schedule: { id: string; cwd: string }, jobId: string) {
  const fired = db.transaction((tx: AgentJobDatabase) => {
    const job = createScheduleJobRecord(tx, schedule, jobId)
    tx.insert(agentScheduleRuns).values({ id: `run-${jobId}`, scheduleId: schedule.id, jobId: job }).run()
    return job
  })
  await recordAgentJobCreated(db, { id: fired } as never, { source: "schedule" })
  return fired
}

