async function apiRunsCreateCommand(options: Options & { env: Record<string, string | undefined> }, request: { prompt: string }) {
  const admission = await submitRun(options.db, request)
  if (options.env.LOCUS_LEGACY_INLINE_API_RUNNER === "1") {
    // optional migration setting re-enabling the old inline core
    return runPreparedLocalJobApiJob(options, admission)
